/* lscm_flatten.c
 * Usage:  ./flatten model.obj
 * Output: patch_<i>.svg  (one per connected surface)
 *
 * Flatten each connected triangle patch of a mesh to 2D using a
 * Least-Squares Conformal Map (preserves angles; area distortion
 * is minimized in the least-squares sense). Exact preservation of
 * both distances and areas is impossible on curved surfaces
 * (Gauss), but patches that are developable come out undistorted.
 *
 * Build:  cc -O2 -o flatten lscm_flatten.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

typedef struct { double x, y, z; } V3;
typedef struct { int a, b, c; } Tri;

static V3 sub3(V3 a, V3 b){ return (V3){a.x-b.x, a.y-b.y, a.z-b.z}; }
static V3 cross3(V3 a, V3 b){
    return (V3){a.y*b.z-a.z*b.y, a.z*b.x-a.x*b.z, a.x*b.y-a.y*b.x};
}
static double dot3(V3 a, V3 b){ return a.x*b.x+a.y*b.y+a.z*b.z; }
static double len3(V3 a){ return sqrt(dot3(a,a)); }

/* ---------------- OBJ loading ---------------- */

static V3  *verts;  static int nverts, capverts;
static Tri *tris;   static int ntris, captris;

static void add_vert(V3 v){
    if(nverts==capverts) capverts = capverts? capverts*2:1024,
        verts = realloc(verts, capverts*sizeof(V3));
    verts[nverts++] = v;
}
static void add_tri(Tri t){
    if(ntris==captris) captris = captris? captris*2:1024,
        tris = realloc(tris, captris*sizeof(Tri));
    tris[ntris++] = t;
}

static void load_obj(const char *path){
    FILE *f = fopen(path,"r");
    if(!f){ fprintf(stderr,"cannot open %s\n",path); exit(1); }
    char line[4096];
    while(fgets(line,sizeof line,f)){
        if(line[0]=='v' && line[1]==' '){
            V3 v; sscanf(line+2,"%lf %lf %lf",&v.x,&v.y,&v.z);
            add_vert(v);
        } else if(line[0]=='f'){
            int i[3]; int n = sscanf(line+1,"%d %d %d",&i[0],&i[1],&i[2]);
            if(n==3){ /* OBJ is 1-based; also strip v/vt/vn via sscanf already done */
                add_tri((Tri){i[0]-1,i[1]-1,i[2]-1});
            }
        }
    }
    fclose(f);
}

/* ---------------- connected components ---------------- */

/* tri adjacency via shared edges */
static int *tadj;          /* ntris*3, -1 = none */
static int *comp_of_tri;   /* component id per triangle */
static int ncomp;

static void build_adjacency(void){
    tadj = malloc(ntris*3*sizeof(int));
    for(int i=0;i<ntris*3;i++) tadj[i]=-1;
    /* edge map: key = 2 sorted vertex ids, hash table */
    int cap = ntris*6*2 + 11;
    typedef struct { int key, tri, which, next; } E;
    E *tab = calloc(cap,sizeof(E));
    int *head = malloc(cap*sizeof(int));
    for(int i=0;i<cap;i++) head[i]=-1;
    int cnt=0;
    #define HASH(a,b) ((unsigned)((a)*73856093u ^ (b)*19349663u) % (unsigned)cap)
    for(int t=0;t<ntris;t++){
        int v[3]={tris[t].a,tris[t].b,tris[t].c};
        for(int k=0;k<3;k++){
            int a=v[k], b=v[(k+1)%3];
            if(a>b){int s=a;a=b;b=s;}
            int h=HASH(a,b);
            for(int e=head[h]; e!=-1; e=tab[e].next){
                if(tab[e].key==(a*1000000+b)){
                    tadj[tab[e].tri*3+tab[e].which]=t;
                    tadj[t*3+k]=tab[e].tri;
                    goto placed;
                }
            }
            tab[cnt].key=a*1000000+b; tab[cnt].tri=t; tab[cnt].which=k;
            tab[cnt].next=head[h]; head[h]=cnt; cnt++;
            placed:;
        }
    }
    free(tab); free(head);
}

static void flood_components(void){
    comp_of_tri = malloc(ntris*sizeof(int));
    for(int i=0;i<ntris;i++) comp_of_tri[i]=-1;
    int *stack = malloc(ntris*sizeof(int));
    ncomp=0;
    for(int s=0;s<ntris;s++){
        if(comp_of_tri[s]!=-1) continue;
        int top=0; stack[top++]=s; comp_of_tri[s]=ncomp;
        while(top){
            int t=stack[--top];
            for(int k=0;k<3;k++){
                int n=tadj[t*3+k];
                if(n!=-1 && comp_of_tri[n]==-1){
                    comp_of_tri[n]=ncomp; stack[top++]=n;
                }
            }
        }
        ncomp++;
    }
    free(stack);
}

/* ---------------- per-patch LSCM solve ---------------- */

/* Sparse symmetric matrix in CSR, solved by CG. Unknowns are 2n
 * (u,v per vertex) but the system decouples into two identical
 * real systems with the same matrix; we solve for u, then reuse
 * the factorization-free CG for v with the same matrix. */

typedef struct { int n; int *rowptr; int *col; double *val; } SM;

static void cg(const SM *A, const double *b, double *x, int maxit){
    int n=A->n;
    double *r=malloc(n*sizeof(double)), *p=malloc(n*sizeof(double)),
           *Ap=malloc(n*sizeof(double));
    for(int i=0;i<n;i++){ x[i]=0; r[i]=b[i]; p[i]=r[i]; }
    double rr=0; for(int i=0;i<n;i++) rr+=r[i]*r[i];
    double rr0=rr? rr:1;
    for(int it=0; it<maxit && rr>1e-20*rr0; it++){
        for(int i=0;i<n;i++){
            double s=0;
            for(int k=A->rowptr[i]; k<A->rowptr[i+1]; k++)
                s += A->val[k]*x[A->col[k]];
            Ap[i]=s;
        }
        double pAp=0; for(int i=0;i<n;i++) pAp+=p[i]*Ap[i];
        if(fabs(pAp)<1e-30) break;
        double alpha=rr/pAp;
        for(int i=0;i<n;i++){ x[i]+=alpha*p[i]; r[i]-=alpha*Ap[i]; }
        double rrn=0; for(int i=0;i<n;i++) rrn+=r[i]*r[i];
        double beta=rrn/rr; rr=rrn;
        for(int i=0;i<n;i++) p[i]=r[i]+beta*p[i];
    }
    free(r); free(p); free(Ap);
}

typedef struct {
    int    nv;        /* vertices in patch (local ids) */
    int   *gidx;      /* global vertex id per local id */
    int   *vmap;      /* global->local, -1 if not in patch */
