/* lscm_flatten.c
 * Usage:  ./flatten model.obj
 * Output: patch_<i>.svg  (one per connected surface)
 *
 * Build:  cc -O2 -o flatten lscm_flatten.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

typedef struct { double x, y, z; } V3;
typedef struct { double re, im;  } C;
typedef struct { int a, b, c;    } Tri;

static C cconj(C z){ return (C){ z.re, -z.im }; }
static C cmul (C a, C b){ return (C){ a.re*b.re - a.im*b.im,
                                       a.re*b.im + a.im*b.re }; }
static C cadd (C a, C b){ return (C){ a.re+b.re, a.im+b.im }; }
static C csub (C a, C b){ return (C){ a.re-b.re, a.im-b.im }; }
static C cscale(C a, double s){ return (C){ a.re*s, a.im*s }; }

static V3 sub3(V3 a, V3 b){ return (V3){a.x-b.x, a.y-b.y, a.z-b.z}; }
static V3 cross3(V3 a, V3 b){
    return (V3){a.y*b.z-a.z*b.y, a.z*b.x-a.x*b.z, a.x*b.y-a.y*b.x};
}
static double dot3(V3 a, V3 b){ return a.x*b.x+a.y*b.y+a.z*b.z; }
static double len3(V3 a){ return sqrt(dot3(a,a)); }

/* ---------------- OBJ loading ---------------- */

static V3  *verts;  static int nverts, capverts;
static Tri *tris;   static int ntris,  captris;

static void add_vert(V3 v){
    if(nverts==capverts){
        capverts = capverts ? capverts*2 : 1024;
        verts = realloc(verts, capverts*sizeof(V3));
    }
    verts[nverts++] = v;
}
static void add_tri(Tri t){
    if(ntris==captris){
        captris = captris ? captris*2 : 1024;
        tris = realloc(tris, captris*sizeof(Tri));
    }
    tris[ntris++] = t;
}

static void load_obj(const char *path){
    FILE *f = fopen(path,"r");
    if(!f){ fprintf(stderr,"cannot open %s\n",path); exit(1); }
    char line[4096];
    while(fgets(line,sizeof line,f)){
        if(line[0]=='v' && (line[1]==' '||line[1]=='\t')){
            V3 v;
            if(sscanf(line+1,"%lf %lf %lf",&v.x,&v.y,&v.z)==3) add_vert(v);
        } else if(line[0]=='f'){
            int i[3];
            /* %d stops at '/', so "f 1/2/3 ..." parses fine */
            if(sscanf(line+1,"%d %d %d",&i[0],&i[1],&i[2])==3){
                /* OBJ indices are 1-based; negative (relative) not handled */
                add_tri((Tri){i[0]-1, i[1]-1, i[2]-1});
            }
        }
    }
    fclose(f);
    fprintf(stderr,"loaded %d vertices, %d triangles\n", nverts, ntris);
}

