static int *tadj;         /* ntris*3: triangle across each edge, -1 = boundary */
static int *comp_of_tri;  static int ncomp;

static void build_adjacency(void){
    tadj = malloc(ntris*3*sizeof(int));
    for(int i=0;i<ntris*3;i++) tadj[i] = -1;

    /* hash table on undirected edges (a,b), a<b */
    int cap = ntris*6*2 + 11;
    typedef struct { long long key; int tri, which, next; } E;
    E *tab = calloc(cap, sizeof(E));
    int *head = malloc(cap*sizeof(int));
    for(int i=0;i<cap;i++) head[i] = -1;
    int cnt = 0;

    for(int t=0;t<ntris;t++){
        int v[3] = { tris[t].a, tris[t].b, tris[t].c };
        for(int k=0;k<3;k++){
            int a=v[k], b=v[(k+1)%3];
            if(a>b){ int s=a; a=b; b=s; }
            long long key = (long long)a*1000003LL + b;
            unsigned h = (unsigned)((key*2654435761LL) % cap);
            int found = -1;
            for(int e=head[h]; e!=-1; e=tab[e].next)
                if(tab[e].key==key){ found=e; break; }
            if(found>=0){
                tadj[tab[found].tri*3 + tab[found].which] = t;
                tadj[t*3+k] = tab[found].tri;
            } else {
                tab[cnt].key=key; tab[cnt].tri=t; tab[cnt].which=k;
                tab[cnt].next=head[h]; head[h]=cnt; cnt++;
            }
        }
    }
    free(tab); free(head);
}

static void flood_components(void){
    comp_of_tri = malloc(ntris*sizeof(int));
    for(int i=0;i<ntris;i++) comp_of_tri[i] = -1;
    int *stack = malloc(ntris*sizeof(int));
    ncomp = 0;
    for(int s=0;s<ntris;s++){
        if(comp_of_tri[s]!=-1) continue;
